// Ask REDLINE output boundary (issue #325).
//
// A live answer is text generated by a language model. Citing a retrieved row ID only shows the
// ID was in the retrieved set (membership); it does NOT show the row supports the sentence
// (entailment). Nothing here can verify an arbitrary scientific statement, so the boundary is
// structural, not lexical:
//   1. Generated prose is always shown inside an "Unverified AI-generated discussion" panel.
//   2. [ID] tokens in the prose never become NASA source links. Known IDs jump to the exact
//      copy of the row below the prose; the NASA link sits only next to that row's own data.
//   3. The rows the prose cites are re-shown verbatim from the data (deterministic summary,
//      draft status, source link), separate from the prose, so the reader compares the two.
//   4. Safety / approval / certification / prediction requests are not sent to the model at all.
//   5. A coarse wording screen withholds generated text that uses decision or absolute-safety
//      language. It is a backstop for obvious cases, not a verifier: text that passes it is
//      still unverified and still labeled so.
// Generated text is display-only: renderAsk returns it flagged { generated: true, verified: false }
// and no triage, brief or result table reads it.
import { citationsIn, isNotFound, NOT_FOUND } from '../rules/retrieve.js';

export const MAX_ANSWER_CHARS = 6000;

export function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// In-page anchor for a retrieved row; IDs come from data, so reduce to a safe token.
export function rowAnchor(id) {
  return `ask-row-${String(id ?? '').replace(/[^A-Za-z0-9_-]/g, '_')}`;
}

// Questions asking REDLINE to decide, approve, certify or predict. The answer to those is a
// fixed boundary notice plus the retrieved test conditions, never generated advice.
const DECISION_REQUEST = [
  /\b(safe|safely|safety[- ]rated|unsafe)\b/i,
  /\b(approv\w*|certif\w*|qualif\w*|accredit\w*|complian\w*|permitted|allowed|acceptable|cleared|sign[- ]?off)\b/i,
  /\b(should|can|could|may)\s+(i|we|they|crews?|nasa)\s+(use|fly|install|put|carry|bring)\b/i,
  /\b(recommend\w*|predict\w*|guarantee\w*)\b/i,
  /\b(will|would|going\s+to)\b[^?.!]*\b(burn|ignite|catch\s+fire|extinguish|spread|explode)\b/i,
];

export function isDecisionRequest(question) {
  const q = String(question ?? '');
  return DECISION_REQUEST.some((re) => re.test(q));
}

export function decisionNoticeHtml() {
  return '<section class="panel" data-role="boundary"><h3 class="type-heading">Outside what REDLINE can answer</h3>' +
    '<p class="type-body">REDLINE does not approve, certify or predict the fire behavior of a material, and does not give safety advice. ' +
    'It shows what burned in testing at the stated conditions, with the NASA source for each row. ' +
    'No live answer was requested for this question. Read the retrieved rows below and their conditions; decisions need the responsible NASA or program safety review.</p></section>';
}

// Coarse screen for decision / absolute-safety wording in generated text (backstop only).
const DECISION_WORDING = [
  /\bsafe\b|\bsafely\b/i,
  /never\s+tested|never\s+burns?|will\s+burn\s+on\s+the\s+moon/i,
  /\bnon[\s-]?flammable\b|\bnonflammable\b|\bfire[\s-]?proof\b|\bincombustible\b/i,
  /\b(approved|certified|certification|qualified\s+for|cleared\s+for|rated\s+for|acceptable\s+for|suitable\s+for|recommended|compliant)\b/i,
  /\b(will|would)\s+(also\s+)?(not\s+)?(self[\s-]?extinguish|extinguish|burn|ignite)\b|\b(won't|cannot|can't)\s+(burn|ignite)\b/i,
];

export function screenGenerated(answer) {
  if (typeof answer !== 'string' || !answer.trim()) return { ok: false, reason: 'malformed' };
  if (answer.length > MAX_ANSWER_CHARS) return { ok: false, reason: 'malformed' };
  if (DECISION_WORDING.some((re) => re.test(answer))) return { ok: false, reason: 'wording' };
  return { ok: true };
}

const WITHHELD = {
  wording: '<p class="caveat type-small">Live answer withheld: it used approval, certification, prediction or absolute wording that goes beyond the evidence. Read the retrieved NASA rows below.</p>',
  malformed: '<p class="caveat type-small">Live answer not shown: the response was empty, too long or not plain text. Read the retrieved NASA rows below.</p>',
};

const UNVERIFIED_NOTE = 'Written by a language model from the retrieved rows. It has not been checked against them and is not a NASA result, a team finding or a safety decision. ' +
  'An ID in brackets only means that row was retrieved; it does not show the row supports the sentence. Compare with the exact row text below.';

// generatedAnswerHtml(answer, hits, { summarize, sourceLink }) -> HTML string.
// summarize/sourceLink are the deterministic row renderers from ask.js.
export function generatedAnswerHtml(answer, hits, { summarize = () => '', sourceLink = () => '' } = {}) {
  const screen = screenGenerated(answer);
  if (!screen.ok) return WITHHELD[screen.reason];
  hits = (Array.isArray(hits) ? hits : []).filter((h) => h && typeof h === 'object');
  const byId = new Map(hits.map((h) => [String(h.id), h]));
  if (isNotFound(answer)) {
    return `<section class="panel" data-role="generated"><p class="type-body">${NOT_FOUND}.</p></section>`;
  }
  const { cited, unknown } = citationsIn(answer, hits);
  const body = esc(answer).replace(/\[([^\]]+)\]/g, (whole, inner) => {
    const parts = inner.split(/[,;]\s*/).map((raw) => {
      const id = raw.trim();
      // `inner` is already escaped text; only known IDs (exact data keys) become in-page links.
      return byId.has(id) ? `<a href="#${rowAnchor(id)}">${id}</a>` : id;
    });
    return `[${parts.join(', ')}]`;
  });
  const exact = cited.map((id) => {
    const h = byId.get(id);
    const status = h.row?.review_status;
    const draft = status && status !== 'verified' ? ` <span class="flag">${esc(status)}: not yet verified</span>` : '';
    return `<li id="${rowAnchor(id)}"><span class="type-data">${esc(id)}</span>${draft}: ${esc(summarize(h))} <span class="type-small">${sourceLink(h.source)}</span></li>`;
  }).join('');
  const drafts = cited.filter((id) => { const s = byId.get(id).row?.review_status; return s && s !== 'verified'; });
  const caveats = [
    unknown.length ? `Caveat: the answer cites ${esc(unknown.join(', '))}, which ${unknown.length > 1 ? 'are' : 'is'} not among the retrieved rows. Do not rely on ${unknown.length > 1 ? 'those' : 'that'} citation.` : '',
    !cited.length ? 'Caveat: the answer cites no retrieved row, so it is not grounded in the sources shown.' : '',
    drafts.length ? `Caveat: ${esc(drafts.join(', '))} ${drafts.length > 1 ? 'are draft rows' : 'is a draft row'}, not yet verified by the team.` : '',
  ].filter(Boolean).map((t) => `<p class="caveat type-small">${t}</p>`).join('');
  return `<section class="panel" data-role="generated" data-verified="false">
    <h3 class="type-heading">AI-generated discussion <span class="flag">Unverified: not checked against the rows</span></h3>
    <p class="type-small text-2">${UNVERIFIED_NOTE}</p>
    <blockquote class="type-body">${body}</blockquote>${caveats}
  </section>${exact ? `<section class="panel" data-role="cited-rows"><h3 class="type-heading">Exact retrieved rows it cites</h3>
    <p class="type-small text-2">Values and conditions below come from the NASA data, not from the generated text.</p><ul>${exact}</ul></section>` : ''}`;
}
